import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test.describe("upload vendor documents", () => {
  test(
    "a file of exactly 10 MiB is accepted",
    { tag: "@DOC-05" },
    async ({ apiAs }) => {
      // Arrange: signed in as a member, with a vendor in status "draft"
      const member = await apiAs("member");
      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("DOC-05 Vendor"),
          category: "software",
          contact_email: `doc05.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@northwind.test`,
        },
      });
      expect(vendorResponse.status()).toBe(201);
      const vendor = await vendorResponse.json();
      expect(vendor.status).toBe("draft");

      const buffer = Buffer.alloc(TEN_MIB, "a");
      expect(buffer.length).toBe(TEN_MIB);

      // Act: upload a text file of exactly 10 MiB as kind "contract"
      const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "contract",
          file: {
            name: "contract-10mib.txt",
            mimeType: "text/plain",
            buffer,
          },
        },
      });

      // Assert
      expect(response.status()).toBe(201);
      const document = await response.json();
      expect(document.kind).toBe("contract");
      expect(document.vendor_id).toBe(vendor.id);
      expect(document.size_bytes).toBe(TEN_MIB);
    },
  );
});
